#include "MedicalWorkflowRuntime.hpp"
namespace elysium::medical {bool MedicalWorkflowRuntime::add(MedicalCase c,std::string&w){if(!c.id||!c.patient){w="invalid case";return false;}return cases_.emplace(c.id,std::move(c)).second;}std::vector<StableId>MedicalWorkflowRuntime::triageOrder()const{std::vector<std::pair<double,StableId>>v;for(auto&[id,c]:cases_)v.push_back({c.threat*2+c.capabilityRisk+c.contamination*.5+(c.transportable?0:.5),id});std::sort(v.begin(),v.end(),[](auto&a,auto&b){return a.first==b.first?a.second<b.second:a.first>b.first;});std::vector<StableId>o;for(auto&x:v)o.push_back(x.second);return o;}bool MedicalWorkflowRuntime::advance(StableId id,TreatmentStage s,const std::vector<StableId>&req,std::string&w){auto i=cases_.find(id);if(i==cases_.end()){w="unknown case";return false;}for(auto r:req){auto x=reservations_.find(r);if(x!=reservations_.end()&&x->second!=id){w="resource unavailable";return false;}}for(auto r:req)reservations_[r]=id;i->second.reservedResources=req;i->second.stage=s;if(s==TreatmentStage::Complete)for(auto r:req)reservations_.erase(r);return true;}}
